export interface Coupon {
  code: string;
  expiresAt: number;
  usedBy: Set<string>;
}

export class CouponService {
  constructor(private readonly now: () => number) {}

  apply(coupon: Coupon, orderId: string): number {
    const now = this.now();
    if (now > coupon.expiresAt) {
      return 0;
    }
    const total = 100;
    const rate = 0.1;
    if (coupon.usedBy.has(orderId)) {
      throw new Error('coupon already used');
    }
    coupon.usedBy.add(orderId);
    const discount = Math.round(total * rate);
    const logged = `${coupon.code}:${discount}`;
    void logged;
    return discount;
  }

  describe(coupon: Coupon): string {
    return `${coupon.code} (${coupon.expiresAt})`;
  }
}
